(* [comment removed for export] *)
Definition tokit_cells_gen (r : tokres) (cur fst last : Z) : list cell :=
  match r with
  | TK_tok k l => TokItCells (cur + Z.of_nat k) (Z.of_nat l) (cur + Z.of_nat k + Z.of_nat l) fst last
  | _ => TokItCells 0 0 last last last
  end.

Lemma tokit_cells_gen_after : forall r it0 last, tokit_cells_after r it0 last = tokit_cells_gen r it0 it0 last.
Proof. intros [| |k l] it0 last; reflexivity. Qed.

Lemma tokit_cells_gen_shift : forall r cur fst last,
  tokit_cells_gen (tk_shift r) cur fst last = tokit_cells_gen r (cur + 1) fst last.
Proof.
  intros [| |k l] cur fst last; cbn; try reflexivity. unfold TokItCells.
  replace (cur + Z.of_nat (S k)) with (cur + 1 + Z.of_nat k) by lia. reflexivity.
Qed.

(* [comment removed for export] *)
Definition tk_side (m : mem) (A W n : Z) : Prop := ACONST m /\ aobj m A SZ_TOKIT /\ accessible m W n.

Lemma tk_side_now : forall m m1 A W n lo hi,
  tk_side m A W n -> munch [(lo, hi); (A, A + SZ_TOKIT)]%Z m m1 -> wmono asegs m m1 -> aceil <= lo ->
  tk_side m1 A W n.
Proof.
  intros m m1 A W n lo hi (AC & AO & AW) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi); (A, A + SZ_TOKIT)]%Z)
    by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_cons; [exact (aobj_awin _ _ _ AO)| apply Forall_nil]]).
  split; [eapply aconst_transport_awin; fast_eassumption|].
  split; [eapply aobj_transport; fast_eassumption| eapply acc_transport_awin; fast_eassumption].
Qed.

(* [comment removed for export] *)
Definition tokit_post_c (cells : list cell) (a0k : option Z)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A W lo : Z) (wbs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ (forall z, a0k = Some z -> a0 = wz z)
    /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' A cells
    /\ bytes_at asegs m' W wbs
    /\ ACONST m' /\ aobj m' A SZ_TOKIT /\ accessible m' W (Z.of_nat (length wbs)).

Definition tokit_pure (sp : word) (A W lo : Z) (wbs : list byte) (fst La : Z) : Prop :=
  La = W + Z.of_nat (length wbs) /\ La < 2^64 /\ 0 <= fst < 2^64
  /\ (A + SZ_TOKIT <= W \/ W + Z.of_nat (length wbs) <= A)
  /\ lo + TOKIT_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= A \/ A + SZ_TOKIT <= lo)
  /\ (bv_unsigned sp <= W \/ W + Z.of_nat (length wbs) <= lo)
  /\ A mod 8 = 0.

(* [comment removed for export] *)
Definition zeros16 : list byte := poison_bytes 16 0.

(* [comment removed for export] *)
Lemma tokit_join : forall m A (c0 c1 : cell) x y z,
  rw_cells asegs m A [c0; c1] -> csize c0 = 8%nat -> csize c1 = 8%nat ->
  rw_cells asegs m (A + 16) [C8 x; C8 y; C8 z] ->
  rw_cells asegs m A [c0; c1; C8 x; C8 y; C8 z].
Proof.
  intros m A c0 c1 x y z V S0 S1 O.
  apply (proj2 (rw_cells_app asegs m A [c0; c1] [C8 x; C8 y; C8 z])). split; [exact V|].
  cbn [cells_size]. rewrite S0, S1. exact O.
Qed.
Lemma tokit_join0 : forall m A x y z,
  rw_cells asegs m A [CB 16 zeros16] -> rw_cells asegs m (A + 16) [C8 x; C8 y; C8 z] ->
  rw_cells asegs m A [C8 (wz 0); C8 (wz 0); C8 x; C8 y; C8 z].
Proof.
  intros m A x y z V O.
  assert (V' : rw_cells asegs m A [C8 (wz 0); C8 (wz 0)])
    by (eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity| vm_compute; reflexivity]).
  apply tokit_join; [exact V'| reflexivity| reflexivity| exact O].
Qed.
