Definition tctor_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v s5v s6v rav : word) (A W lo : Z) (wbs : list byte) (cur fst La : Z) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -64) [C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 A [CB 16 zeros16]
  /\ rw_cells asegs m1 (A + 16) [C8 (wz cur); C8 (wz fst); C8 (wz La)]
  /\ bytes_at asegs m1 W wbs
  /\ stk asegs m1 lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ tk_side m A W (Z.of_nat (length wbs)).

Local Ltac open_tctx CTX PURE :=
  destruct CTX as (FR & V & OBJ & WIN & ST & MU & WM & MI & SD);
  destruct PURE as (HLA & LA64 & FST & SEPW & LO & CEIL & SEPA & SEPS & AL);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aobj_pos _ _ _ (proj1 (proj2 SD))) as (A0 & _ & AHI);
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPW; hydeL SEPA; hydeL SEPS; hydeL AL;
  unfold TokItCells, SZ_TOKIT, TOKIT_STACK, AINTRIN_STACK, AAPP_HI in *.

