Lemma tctor_tok : forall (k i j : nat) (itv : Z) rax ra sp gp tp t0 t1 t2 a1x a4x a5x a6x a7x s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (Fi La : Z),
  (length wbs - j = k)%nat -> (i < j)%nat -> (j <= length wbs)%nat ->
