Local Ltac tctor_ctx_close := unfold tctor_ctx, tk_side, SZ_TOKIT, wz; repeat (split; [fast_eassumption|]); fast_eassumption.

(* [comment removed for export] *)
Lemma tctor_scan : forall (mu : nat) (ph : bool) (i : nat) rax ra sp gp tp t0 t1 t2 a0x a6x a7x s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (Fi La : Z),
  (2 * (length wbs - i) + (if ph then 1 else 0) < mu)%nat ->
  (i <= length wbs)%nat -> (ph = true -> (i < length wbs)%nat) ->
  (ph = false -> forall b, nth_error wbs i = Some b -> is_ws (zb b) = false) ->
  tctor_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v ra A W lo wbs (W + Z.of_nat i) Fi La -> tokit_pure sp A W lo wbs Fi La ->
  evt asegs (tokit_post_c (tokit_cells_gen (tok_next false (skipn i (zbytes wbs))) (W + Z.of_nat i) Fi La) None
               ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 F fc A W lo wbs m)
    (MS (tctor_regs rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 La
                    (if ph then wz (W + Z.of_nat i) else a0x) (Z_to_bv 64 (Z.shiftr (A + 24) 3 + 2147450880)) a6x a7x
                    (W + Z.of_nat i) A s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 (if ph then 0xbd098 else 0xbd0dc)) fc None m1 (seg_rom asegs)).
